INSERT OR IGNORE INTO emails (id, folder_id, subject, sender, recipient, date, read, starred, body, in_reply_to, email_references, thread_id, message_id, raw_headers, cc, bcc) VALUES
('sam-16-e1', 'inbox', '[요청] 갤럭시 S25 Edge Landing Page Banner 디자인 의뢰', 'jimin.oh@samsung.com', 'bzengage@example.com', '2026-05-10T00:00:00.000Z', 0, 0, '<html><body>\n<p>비즈매트릭스 팀, 안녕하세요.</p>\n<p><strong>갤럭시 S25 Edge</strong> 신제품 런칭을 위한 <strong>Landing Page Banner</strong> 디자인 및 개발을 요청드립니다.</p>\n<h3>요청 사항:</h3>\n<ul>\n<li>메인 비주얼: 제품 이미지 중심의 클린한 디자인</li>\n<li>카피: "갤럭시 S25 Edge — 혁신을 일상으로"</li>\n<li>CTA 버튼: "지금 구매하기" / "자세히 보기"</li>\n<li>반응형 대응 (PC/Mobile/Tablet)</li>\n</ul>\n<p>런칭 일정: <strong>6월 1일</strong></p>\n<p>1차 시안은 <strong>2026-05-10 이후 3영업일</strong> 내로 부탁드립니다.</p>\n<p>감사합니다.<br>오지민 드림<br>삼성전자 디지털마케팅팀</p>\n</body></html>', NULL, NULL, 'thread-samsung-16', 'msg-sam-16-e1', '[{"key":"from","value":"오지민 <jimin.oh@samsung.com>"},{"key":"to","value":"bzengage@example.com"},{"key":"subject","value":"[요청] 갤럭시 S25 Edge Landing Page Banner 디자인 의뢰"},{"key":"date","value":"2026-05-10T00:00:00.000Z"},{"key":"message-id","value":"<msg-sam-16-e1>"}]', NULL, NULL);
INSERT OR IGNORE INTO emails (id, folder_id, subject, sender, recipient, date, read, starred, body, in_reply_to, email_references, thread_id, message_id, raw_headers, cc, bcc) VALUES
('sam-16-e2', 'sent', 'Re: [요청] 갤럭시 S25 Edge Landing Page Banner 디자인 의뢰', 'bzengage@example.com', 'jimin.oh@samsung.com', '2026-05-12T05:30:00.000Z', 1, 0, '<html><body>\n<p>오지민 님, 안녕하세요.</p>\n<p><strong>갤럭시 S25 Edge</strong> Landing Page Banner 1차 시안을 준비했습니다.</p>\n<h3>시안 개요:</h3>\n<ul>\n<li>메인 비주얼: 제품 3D 렌더링 이미지 + 그라데이션 배경</li>\n<li>카피 적용 완료</li>\n<li>PC/Mobile 반응형 레이아웃 적용</li>\n</ul>\n<p>첨부 파일에서 시안을 확인해 주시고, 피드백 부탁드립니다.</p>\n<p>감사합니다.<br>비즈매트릭스 팀</p>\n</body></html>', 'msg-sam-16-e1', '["msg-sam-16-e1"]', 'thread-samsung-16', 'msg-sam-16-e2', '[{"key":"from","value":"비즈매트릭스 <bzengage@example.com>"},{"key":"to","value":"jimin.oh@samsung.com"},{"key":"subject","value":"Re: [요청] 갤럭시 S25 Edge Landing Page Banner 디자인 의뢰"},{"key":"date","value":"2026-05-12T05:30:00.000Z"},{"key":"message-id","value":"<msg-sam-16-e2>"},{"key":"in-reply-to","value":"<msg-sam-16-e1>"},{"key":"references","value":"<msg-sam-16-e1>"}]', NULL, NULL);
INSERT OR IGNORE INTO emails (id, folder_id, subject, sender, recipient, date, read, starred, body, in_reply_to, email_references, thread_id, message_id, raw_headers, cc, bcc) VALUES
('sam-16-e3', 'inbox', 'Re: [요청] 갤럭시 S25 Edge Landing Page Banner 디자인 의뢰 - 수정 요청', 'jimin.oh@samsung.com', 'bzengage@example.com', '2026-05-13T01:15:00.000Z', 1, 0, '<html><body>\n<p>비즈매트릭스 팀, 안녕하세요.</p>\n<p>1차 시안 확인했습니다. 전반적으로 좋습니다만, <strong>아래 수정 사항</strong>을 반영 부탁드립니다.</p>\n<h3>수정 요청 사항:</h3>\n<ol>\n<li>메인 비주얼 배경색을 <strong>삼성 네이비</strong> 톤으로 변경</li>\n<li>CTA 버튼 색상을 삼성 브랜드 컬러(#1428A0)로 조정</li>\n<li>모바일 버전에서 폰트 사이즈 1pt 업</li>\n<li>하단에 <strong>"사양 자세히 보기"</strong> 링크 추가</li>\n</ol>\n<p>수정본은 <strong>2026-05-13 이후 2영업일</strong> 내로 부탁드립니다.</p>\n<p>감사합니다.<br>오지민 드림</p>\n</body></html>', 'msg-sam-16-e2', '["msg-sam-16-e1","msg-sam-16-e2"]', 'thread-samsung-16', 'msg-sam-16-e3', '[{"key":"from","value":"오지민 <jimin.oh@samsung.com>"},{"key":"to","value":"bzengage@example.com"},{"key":"subject","value":"Re: [요청] 갤럭시 S25 Edge Landing Page Banner 디자인 의뢰 - 수정 요청"},{"key":"date","value":"2026-05-13T01:15:00.000Z"},{"key":"message-id","value":"<msg-sam-16-e3>"},{"key":"in-reply-to","value":"<msg-sam-16-e2>"},{"key":"references","value":"<msg-sam-16-e1> <msg-sam-16-e2>"}]', NULL, NULL);
