('sam-18-e1', 'inbox', '[요청] 갤럭시 링 SNS 광고 배너 디자인 의뢰', 'chaewon.shin@samsung.com', 'bzengage@example.com', '2026-05-14T00:00:00.000Z', 0, 0, '<html><body>\n<p>비즈매트릭스 팀, 안녕하세요.</p>\n<p><strong>갤럭시 링</strong> 신제품 런칭을 위한 <strong>SNS 광고 배너</strong> 디자인 및 개발을 요청드립니다.</p>\n<h3>요청 사항:</h3>\n<ul>\n<li>메인 비주얼: 제품 이미지 중심의 클린한 디자인</li>\n<li>카피: "갤럭시 링 — 혁신을 일상으로"</li>\n<li>CTA 버튼: "지금 구매하기" / "자세히 보기"</li>\n<li>반응형 대응 (PC/Mobile/Tablet)</li>\n</ul>\n<p>런칭 일정: <strong>6월 1일</strong></p>\n<p>1차 시안은 <strong>2026-05-14 이후 3영업일</strong> 내로 부탁드립니다.</p>\n<p>감사합니다.<br>신채원 드림<br>삼성전자 글로벌캠페인팀</p>\n</body></html>', NULL, NULL, 'thread-samsung-18', 'msg-sam-18-e1', '[{"key":"from","value":"신채원 <chaewon.shin@samsung.com>"},{"key":"to","value":"bzengage@example.com"},{"key":"subject","value":"[요청] 갤럭시 링 SNS 광고 배너 디자인 의뢰"},{"key":"date","value":"2026-05-14T00:00:00.000Z"},{"key":"message-id","value":"<msg-sam-18-e1>"}]', NULL, NULL);
INSERT OR IGNORE INTO emails (id, folder_id, subject, sender, recipient, date, read, starred, body, in_reply_to, email_references, thread_id, message_id, raw_headers, cc, bcc) VALUES
