INSERT OR IGNORE INTO emails (id, folder_id, subject, sender, recipient, date, read, starred, body, in_reply_to, email_references, thread_id, message_id, raw_headers, cc, bcc) VALUES
('recent-s1', 'inbox', '[공지] 삼성전자 2026 상반기 디지털 마케팅 가이드라인 업데이트', 'notice@samsung.com', 'bzengage@example.com', '2026-05-12T09:00:00.000Z', 0, 1, '<html><body>\n<h2>📋 2026 상반기 가이드라인 업데이트 안내</h2>\n<p>비즈매트릭스 팀, 안녕하세요.</p>\n<p>삼성전자 디지털 마케팅 가이드라인이 업데이트되었습니다.</p>\n<ul>\n<li>브랜드 컬러 팔레트 2026 버전 적용</li>\n<li>Galaxy AI 관련 비주얼 가이드 신규 추가</li>\n<li>모바일 퍼스트 레이아웃 원칙 강화</li>\n</ul>\n<p>첨부 PDF를 확인해 주시기 바랍니다.</p>\n<p>삼성전자 브랜드마케팅팀 드림</p>\n</body></html>', NULL, NULL, 'recent-s1', 'msg-recent-s1', '[{"key":"from","value":"삼성전자 <notice@samsung.com>"},{"key":"to","value":"bzengage@example.com"},{"key":"subject","value":"[공지] 삼성전자 2026 상반기 디지털 마케팅 가이드라인 업데이트"},{"key":"date","value":"2026-05-12T09:00:00.000Z"},{"key":"message-id","value":"<msg-recent-s1>"}]', NULL, NULL);
INSERT OR IGNORE INTO emails (id, folder_id, subject, sender, recipient, date, read, starred, body, in_reply_to, email_references, thread_id, message_id, raw_headers, cc, bcc) VALUES
('recent-s2', 'inbox', '[긴급] 갤럭시 S25 Edge 런칭 일정 앞당김 — 즉시 확인 요청', 'jimin.oh@samsung.com', 'bzengage@example.com', '2026-05-16T08:00:00.000Z', 0, 1, '<html><body>\n<p>비즈매트릭스 팀, 안녕하세요. 오지민 입니다.</p>\n<p><strong>긴급 공지</strong>드립니다.</p>\n<p>갤럭시 S25 Edge 글로벌 런칭 일정이 <strong>6월 15일 → 5월 29일</strong>로 앞당겨졌습니다.</p>\n<table border="1" cellpadding="6">\n<tr><th>배너 종류</th><th>기존 마감</th><th>변경 마감</th></tr>\n<tr><td>홈페이지 메인</td><td>6월 5일</td><td>5월 22일</td></tr>\n<tr><td>모바일 앱 푸시</td><td>6월 8일</td><td>5월 24일</td></tr>\n<tr><td>이메일 뉴스레터</td><td>6월 10일</td><td>5월 26일</td></tr>\n</table>\n<p>일정 조율 가능 여부를 <strong>오늘 중</strong>으로 회신 부탁드립니다.</p>\n<p>감사합니다.<br>오지민 드림</p>\n</body></html>', NULL, NULL, 'recent-s2', 'msg-recent-s2', '[{"key":"from","value":"오지민 <jimin.oh@samsung.com>"},{"key":"to","value":"bzengage@example.com"},{"key":"subject","value":"[긴급] 갤럭시 S25 Edge 런칭 일정 앞당김 — 즉시 확인 요청"},{"key":"date","value":"2026-05-16T08:00:00.000Z"},{"key":"message-id","value":"<msg-recent-s2>"}]', NULL, NULL);
INSERT OR IGNORE INTO emails (id, folder_id, subject, sender, recipient, date, read, starred, body, in_reply_to, email_references, thread_id, message_id, raw_headers, cc, bcc) VALUES
('recent-s3', 'inbox', '[신규 의뢰] 갤럭시 링 SNS 캠페인 배너 제작 요청', 'subeen.baek@samsung.com', 'bzengage@example.com', '2026-05-20T10:30:00.000Z', 0, 0, '<html><body>\n<p>비즈매트릭스 팀, 안녕하세요. 삼성전자 프로덕트마케팅팀 백수빈입니다.</p>\n<p><strong>갤럭시 링</strong> 신제품 출시에 맞춰 SNS 캠페인 배너 제작을 의뢰드립니다.</p>\n<h3>요청 상세:</h3>\n<ul>\n<li>채널: Instagram, Facebook, X(트위터)</li>\n<li>사이즈: 1:1 (1080x1080), 4:5 (1080x1350), 16:9 (1920x1080)</li>\n<li>콘셉트: "건강한 일상, 갤럭시 링과 함께"</li>\n<li>희망 납기: <strong>5월 27일</strong></li>\n</ul>\n<p>견적 및 일정 확인 후 회신 부탁드립니다.</p>\n<p>감사합니다.<br>백수빈 드림<br>삼성전자 프로덕트마케팅팀</p>\n</body></html>', NULL, NULL, 'recent-s3', 'msg-recent-s3', '[{"key":"from","value":"백수빈 <subeen.baek@samsung.com>"},{"key":"to","value":"bzengage@example.com"},{"key":"subject","value":"[신규 의뢰] 갤럭시 링 SNS 캠페인 배너 제작 요청"},{"key":"date","value":"2026-05-20T10:30:00.000Z"},{"key":"message-id","value":"<msg-recent-s3>"}]', NULL, NULL);
